import React from 'react';
import { Link } from 'react-router-dom';
import '../styles/index.css'

const NavBar = () => {
  return (
    <nav className="bg-gray-600">

          <div className=" items-center justify-center sm:justify-center">

            <div className="hidden sm:block sm:ml-6 items-center justify-center">
              <div className="flex space-x-4">
                <Link to="/" className="text-gray-300 hover:bg-gray-700 hover:text-white px-3 py-2 rounded-md text-sm font-medium">Home</Link>
                <Link to="/about" className="text-gray-300 hover:bg-gray-700 hover:text-white px-3 py-2 rounded-md text-sm font-medium">About</Link>
                <Link to="/projects" className="text-gray-300 hover:bg-gray-700 hover:text-white px-3 py-2 rounded-md text-sm font-medium">Projects</Link>
                <Link to="/socials" className="text-gray-300 hover:bg-gray-700 hover:text-white px-3 py-2 rounded-md text-sm font-medium">Socials</Link>
              </div>
            </div>
          </div>
    </nav>
  );
};

export default NavBar;
